  bind('.nr-speak','click',(e,el)=>{const voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&/^en[-_]US$/i.test(v.lang));if(!voice){announce('当前浏览器暂无本地美式语音，请在应用内体验朗读');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(el.dataset.speak);u.voice=voice;u.lang='en-US';speechSynthesis.speak(u);});
